INSERT INTO detection_rules (id, rule_id, name, mitre_ttp, severity, description, tags, risk_score_default, is_active, conditions, match_type, created_at, updated_at) VALUES
(gen_random_uuid(), 'DET-005', 'PowerShell con comando codificado/ofuscado', 'T1059.001', 'high', 'PowerShell invocado con comando Base64/oculto (-enc, FromBase64String, -w hidden, IEX). Técnica de ejecución ofuscada usada por la mayoría del malware moderno.', '["execution", "powershell", "obfuscation"]'::jsonb, 0.8, true, '[{"field": "process", "op": "contains", "value": "powershell"}, {"field": "command_line", "op": "contains_any", "value": ["-enc", "-encodedcommand", "frombase64string", "-w hidden", "-windowstyle hidden", "-nop", "iex ", "invoke-expression"]}]'::jsonb, 'all', now(), now()),
(gen_random_uuid(), 'DET-006', 'Abuso de LOLBin (certutil/mshta/regsvr32/rundll32)', 'T1218', 'high', 'Binario legítimo del sistema (LOLBin) usado para descargar o ejecutar código: certutil -urlcache, mshta javascript, regsvr32 scrobj. Evasión de listas blancas.', '["defense-evasion", "lolbin"]'::jsonb, 0.75, true, '[{"field": "process", "op": "contains_any", "value": ["certutil.exe", "mshta.exe", "regsvr32.exe", "rundll32.exe", "bitsadmin.exe"]}, {"field": "command_line", "op": "contains_any", "value": ["http", "-urlcache", "javascript:", "scrobj", ".sct", "downloadstring", "/i:"]}]'::jsonb, 'all', now(), now()),
(gen_random_uuid(), 'DET-007', 'Volcado de credenciales / acceso a LSASS', 'T1003', 'critical', 'Indicadores de volcado de credenciales: mimikatz/sekurlsa, procdump sobre lsass, comsvcs.dll MiniDump. Acceso al proceso LSASS para robar hashes/tickets.', '["credential-access", "lsass"]'::jsonb, 0.95, true, '[{"field": "process", "op": "contains_any", "value": ["mimikatz", "procdump"]}, {"field": "command_line", "op": "contains_any", "value": ["sekurlsa", "lsass.dmp", "comsvcs.dll", "minidump", "lsass.exe"]}]'::jsonb, 'any', now(), now()),
(gen_random_uuid(), 'DET-008', 'Tarea programada sospechosa (persistencia)', 'T1053.005', 'medium', 'Creación de tarea programada (schtasks /create) — mecanismo común de persistencia y ejecución diferida.', '["persistence", "scheduled-task"]'::jsonb, 0.55, true, '[{"field": "command_line", "op": "contains", "value": "schtasks"}, {"field": "command_line", "op": "contains_any", "value": ["/create", "-create"]}]'::jsonb, 'all', now(), now()),
(gen_random_uuid(), 'DET-009', 'Creación de servicio para persistencia', 'T1543.003', 'medium', 'Alta de servicio de Windows (sc create / New-Service) usada para persistencia con privilegios de sistema.', '["persistence", "service"]'::jsonb, 0.55, true, '[{"field": "command_line", "op": "contains", "value": "sc create"}, {"field": "command_line", "op": "contains", "value": "sc.exe create"}, {"field": "command_line", "op": "contains", "value": "new-service"}]'::jsonb, 'any', now(), now()),
(gen_random_uuid(), 'DET-010', 'Desactivación de defensas (AV/Firewall)', 'T1562.001', 'high', 'Intento de desactivar Windows Defender o el firewall: Set-MpPreference -DisableRealtimeMonitoring, netsh advfirewall off, Stop-Service WinDefend.', '["defense-evasion", "impair-defenses"]'::jsonb, 0.8, true, '[{"field": "command_line", "op": "contains", "value": "disablerealtimemonitoring"}, {"field": "command_line", "op": "contains", "value": "advfirewall set allprofiles state off"}, {"field": "command_line", "op": "contains", "value": "stop-service windefend"}, {"field": "command_line", "op": "contains", "value": "add-mppreference -exclusionpath"}]'::jsonb, 'any', now(), now()),
(gen_random_uuid(), 'DET-011', 'Borrado de registros de eventos', 'T1070.001', 'high', 'Limpieza de logs de Windows (wevtutil cl / Clear-EventLog) — anti-forense para borrar rastros tras el compromiso.', '["defense-evasion", "indicator-removal"]'::jsonb, 0.8, true, '[{"field": "command_line", "op": "contains", "value": "wevtutil cl"}, {"field": "command_line", "op": "contains", "value": "wevtutil clear-log"}, {"field": "command_line", "op": "contains", "value": "clear-eventlog"}]'::jsonb, 'any', now(), now()),
(gen_random_uuid(), 'DET-012', 'Ejecución vía WMI', 'T1047', 'medium', 'Ejecución de procesos mediante WMI (wmic process call create / Invoke-WmiMethod Win32_Process) — usado para movimiento lateral y ejecución sigilosa.', '["execution", "wmi", "lateral-movement"]'::jsonb, 0.6, true, '[{"field": "command_line", "op": "contains", "value": "process call create"}, {"field": "command_line", "op": "contains", "value": "invoke-wmimethod"}, {"field": "command_line", "op": "contains", "value": "win32_process"}]'::jsonb, 'any', now(), now()),
(gen_random_uuid(), 'DET-013', 'Abuso de BITS para transferencia', 'T1197', 'medium', 'Uso de BITS (bitsadmin /transfer, Start-BitsTransfer) para descargar cargas evadiendo controles de red.', '["defense-evasion", "bits"]'::jsonb, 0.6, true, '[{"field": "command_line", "op": "contains", "value": "bitsadmin /transfer"}, {"field": "command_line", "op": "contains", "value": "start-bitstransfer"}]'::jsonb, 'any', now(), now()),
(gen_random_uuid(), 'DET-014', 'Indicadores de reverse shell / C2 interactivo', 'T1059', 'high', 'Patrones de shell inverso: TcpClient de PowerShell, /dev/tcp, netcat -e. Canal de comando y control interactivo.', '["command-and-control", "reverse-shell"]'::jsonb, 0.85, true, '[{"field": "command_line", "op": "contains", "value": "system.net.sockets.tcpclient"}, {"field": "command_line", "op": "contains", "value": "/dev/tcp/"}, {"field": "command_line", "op": "contains", "value": "nc -e"}, {"field": "command_line", "op": "contains", "value": "ncat -e"}]'::jsonb, 'any', now(), now())
